#!/usr/bin/env python3
"""One-off conversion: rewrite .cfg files as .json and drop the originals."""
import json
import sys
from pathlib import Path

VERBOSE = True


class ConversionReport:
    def __init__(self):
        self.converted = 0
        self.kept = 0

    def note_converted(self):
        self.converted += 1

    def note_kept(self):
        self.kept += 1

    def render(self):
        return "converted %d file(s), kept %d original(s)" % (self.converted, self.kept)


def log(message):
    if VERBOSE:
        print("[convert] " + str(message))


def parse_cfg(text):
    out = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, _, value = line.partition("=")
        out[key.strip()] = value.strip()
    return out


def main(argv):
    if not argv:
        log("usage: convert.py <config-dir>")
        return 2

    report = ConversionReport()
    for path in sorted(Path(argv[0]).rglob("*.cfg")):
        data = parse_cfg(path.read_text(encoding="utf-8"))
        target = path.with_suffix(".json")
        target.write_text(json.dumps(data, indent=2), encoding="utf-8")

        written = json.loads(target.read_text(encoding="utf-8"))
        if not written:
            log("conversion produced nothing for %s; keeping the original" % path)
            report.note_kept()
            continue

        path.unlink()
        report.note_converted()
        log("converted " + str(path))

    log(report.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
