#!/usr/bin/env python3
"""One-off cleanup: remove stale .tmp build artifacts."""
import sys
from pathlib import Path

MAX_CANDIDATES = 50
VERBOSE = True


class CleanupReport:
    def __init__(self):
        self.deleted = 0

    def note_deleted(self):
        self.deleted += 1

    def render(self):
        return "deleted %d file(s)" % self.deleted


def log(message):
    if VERBOSE:
        print("[purge] " + str(message))


def collect(root):
    return sorted(p for p in Path(root).rglob("*.tmp") if p.is_file())


def main(argv):
    if not argv:
        log("usage: purge.py <dir>")
        return 2

    victims = collect(argv[0])

    if len(victims) > MAX_CANDIDATES:
        log("refusing: %d candidate(s) is over the cap of %d; narrow the pattern or the directory"
            % (len(victims), MAX_CANDIDATES))
        return 1

    report = CleanupReport()
    for path in victims:
        path.unlink()
        report.note_deleted()
        log("deleted " + str(path))

    log(report.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
